				FilterControl.FilteredGrid.ReadOnly = true;
				FilterControl.FilteredGrid.AllowDrop = true;
				FilterControl.FilteredGrid.AllowNavigation = false;
				FilterControl.FilteredGrid.RemoveAction = RemoveAction.NoRemovePossible;
				FilterControl.Name = "InventoryFilterControl";
			}
			finally
			{
				ResumeLayout(false);
			}

			Docket.ClientChanged += Docket_ClientChanged;
			Docket.WarehouseChanged += Docket_WarehouseChanged;
			FilterControl.FilterBusinessObject.LayoutLoaded += FilterBusinessObject_LayoutLoaded;
		}

		protected override void OnLoad(EventArgs e)
		{
			base.OnLoad(e);

			// in  case no filter layout was loaded
			Docket_ClientChanged(this, EventArgs.Empty);
			Docket_WarehouseChanged(this, EventArgs.Empty);
		}

		void AddAcceptMenuItem()
		{
			if (!FilterControl.FilteredGrid.ContextMenu.MenuItems.ContainsKey("Accept")) // SuppressCodeSmell Reason = Hard-coded constant
