				MenuItem item = new ZMenuItem(ResString.GetMultilingualString("WhsInventoryFilterControl|Accept", "Accept"), new EventHandler(OnAcceptMenuItemClick));
				FilterControl.FilteredGrid.ContextMenu.MenuItems.Add(item);
				item.Name = "Accept";
