		void HandleAcceptMenuClick()
		{
			if (FilterControl.FilteredGrid.SelectedElements.Length > 0)
			{
				if (Docket is ICreateDocketLineFromInventory docketThatCanCreateDocketLine)
				{
					docketThatCanCreateDocketLine.AcceptInventoryLinesFromSearchGrid(FilterControl.FilteredGrid.SelectedElements);
